import {people} from './people-data.js';
const T=(fr,ar,en,es)=>({fr,ar,en,es});
const labels={nav:T('Personnalités','شخصيات','People','Personajes'),tag:T('Les voix & les visages','أصوات ووجوه','Voices & faces','Voces y rostros'),title:T('Tétouan, à travers ses talents.','تطوان من خلال مبدعيها.','Tétouan through its talents.','Tetuán a través de su talento.'),intro:T('Des figures de l’histoire aux créateurs d’aujourd’hui : découvrez leurs parcours et leurs liens documentés avec la ville.','من شخصيات التاريخ إلى مبدعي اليوم: اكتشف مساراتهم وصلاتهم الموثقة بالمدينة.','From historical figures to contemporary creators: discover their lives and documented connections with the city.','De las figuras históricas a los creadores actuales: descubre sus trayectorias y sus vínculos documentados con la ciudad.'),all:T('Tous','الكل','All','Todos'),history:T('Histoire','تاريخ','History','Historia'),music:T('Musique','موسيقى','Music','Música'),screen:T('Acteurs & actrices','ممثلون وممثلات','Actors & actresses','Actores y actrices'),art:T('Arts plastiques','فنون تشكيلية','Visual arts','Artes plásticas'),cinema:T('Cinéma','سينما','Cinema','Cine'),search:T('Chercher une personnalité…','ابحث عن شخصية…','Find a person…','Buscar un personaje…'),more:T('Découvrir son parcours','اكتشف المسار','Discover their story','Descubrir su trayectoria'),connection:T('Le lien avec Tétouan','الارتباط بتطوان','Connection with Tétouan','El vínculo con Tetuán'),references:T('Références & photographie','المراجع والصورة','References & photograph','Referencias y fotografía'),play:T('Regarder ici','شاهد هنا','Watch here','Ver aquí'),external:T('Ouvrir sur YouTube','افتح في يوتيوب','Open on YouTube','Abrir en YouTube'),media:T('À écouter & à découvrir','استمع واكتشف','Listen & discover','Escuchar y descubrir'),videoNote:T('La vidéo se charge après votre clic. Si la lecture intégrée est indisponible, utilisez le lien YouTube.','يحمل الفيديو بعد النقر. إذا لم تتوفر القراءة داخل الموقع، استعمل رابط يوتيوب.','The video loads when you click. If embedded playback is unavailable, use the YouTube link.','El vídeo se carga al pulsar. Si no se permite la reproducción integrada, utiliza el enlace de YouTube.'),empty:T('Aucun résultat pour cette recherche.','لا نتائج لهذا البحث.','No results for this search.','No hay resultados para esta búsqueda.'),portrait:T('Photographie / document','صورة / وثيقة','Photograph / document','Fotografía / documento')};
export function createPeopleFeature({text,escape,icon,head,normalize}){
 let category='all',query='';const label=k=>text(labels[k]);
 const portrait=p=>`<img src="${escape(p.portrait.src)}" alt="${escape(text(p.portrait.caption))}" width="${p.portrait.width}" height="${p.portrait.height}" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-person-image="${p.id}" class="person-image ${p.portrait.kind==='portrait'?'':'historical-document'}">`;
 const filtered=()=>people.filter(p=>(category==='all'||p.categories.includes(category))&&normalize(`${Object.values(p.name).join(' ')} ${Object.values(p.summary).join(' ')} ${Object.values(p.role).join(' ')}`).includes(normalize(query)));
 const cards=()=>filtered().map(p=>`<article class="person-card"><a class="person-photo" href="#/personne/${p.id}">${portrait(p)}<span>${escape(text(p.role))}</span></a><div class="person-copy"><small>${p.categories.map(label).join(' · ')}</small><h2><a href="#/personne/${p.id}">${escape(text(p.name))}</a></h2><p>${escape(text(p.connection))}</p><a class="text-button" href="#/personne/${p.id}">${label('more')}${icon('chevron')}</a></div></article>`).join('')||`<p class="empty">${label('empty')}</p>`;
 function page(){return `<div class="wrap people-page">${head(label('tag'),label('title'),label('intro'))}<div class="category-tabs">${['all','history','music','screen','art','cinema'].map(c=>`<button class="chip ${c===category?'active':''}" data-person-filter="${c}" aria-pressed="${c===category}">${label(c)}</button>`).join('')}</div><div class="page-tools"><label class="search-inline">${icon('search')}<input id="people-query" type="search" value="${escape(query)}" placeholder="${label('search')}" aria-label="${label('search')}"></label><span data-people-count aria-live="polite">${filtered().length} / ${people.length}</span></div><section class="people-grid" data-people-cards>${cards()}</section></div>`;}
 function refresh(){const root=document.querySelector('[data-people-cards]');if(!root)return;root.innerHTML=cards();document.querySelector('[data-people-count]').textContent=`${filtered().length} / ${people.length}`;document.querySelectorAll('[data-person-filter]').forEach(b=>{const on=b.dataset.personFilter===category;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});}
 function musicPanel(p){const v=p.musicEmbed;if(!v||v.platform!=='spotify'||!/^[A-Za-z0-9]{22}$/.test(v.id))return '';return `<section class="person-videos"><h3>${label('media')}</h3><article class="person-video"><h4>${escape(v.title)}</h4><div class="video-frame spotify-frame" data-spotify-frame><button class="video-start" data-person-spotify="${p.id}"><span>${icon('play')}</span>${text(T('Écouter ici','استمع هنا','Listen here','Escuchar aquí'))}<small>Spotify · ${escape(v.channel)}</small></button></div><p>${escape(text(v.credit))}</p><a class="text-button" href="${escape(v.url)}" target="_blank" rel="noopener noreferrer">Spotify${icon('chevron')}</a></article></section>`;}
 function profile(id){const p=people.find(p=>p.id===id);if(!p)return null;return `<button class="icon-button dialog-close" data-close aria-label="${text(T('Fermer','إغلاق','Close','Cerrar'))}">${icon('close')}</button><div class="person-profile-photo">${portrait(p)}</div><div class="detail-credit">${escape(text(p.portrait.caption))} · ${escape(p.portrait.author)}</div><div class="detail-body"><div class="eyebrow">${escape(text(p.role))}</div><h2 id="detail-title">${escape(text(p.name))}</h2><p>${escape(text(p.summary))}</p><h3>${label('connection')}</h3><p>${escape(text(p.connection))}</p>${p.videos?.length?`<section class="person-videos"><h3>${label('media')}</h3><p class="source-caption">${label('videoNote')}</p>${p.videos.map(v=>`<article class="person-video"><h4>${escape(v.title)}</h4><div class="video-frame" data-video-frame="${escape(v.id)}"><button class="video-start" data-person-video="${escape(v.id)}" aria-label="${label('play')} · ${escape(v.title)}"><span>${icon('play')}</span>${label('play')}<small>${escape(v.channel)}</small></button></div><p>${escape(text(v.credit))}</p><a class="text-button" href="${escape(v.url)}" target="_blank" rel="noopener noreferrer">${label('external')}${icon('chevron')}</a></article>`).join('')}</section>`:''}${musicPanel(p)}<h3>${label('references')}</h3><div class="detail-source">${p.references.map(r=>`<a href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">${escape(r.name)}</a>`).join('')}<a href="${escape(p.portrait.source)}" target="_blank" rel="noopener noreferrer">${label('portrait')}</a></div><p class="source-caption">${escape(p.portrait.author)} · <a href="${escape(p.portrait.licenseUrl||p.portrait.source)}" target="_blank" rel="noopener noreferrer">${escape(p.portrait.license)}</a></p></div>`;}
 document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.personFilter){category=b.dataset.personFilter;refresh();}if(b.dataset.personSpotify){const v=people.find(p=>p.id===b.dataset.personSpotify)?.musicEmbed;if(v?.platform==='spotify'&&/^[A-Za-z0-9]{22}$/.test(v.id)){document.dispatchEvent(new Event('tetouan-video-start'));b.closest('[data-spotify-frame]').innerHTML=`<iframe src="https://open.spotify.com/embed/album/${v.id}?utm_source=generator" title="${escape(v.title)}" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" allowfullscreen loading="lazy"></iframe>`;}}if(b.dataset.personVideo){const id=b.dataset.personVideo,v=people.flatMap(p=>p.videos||[]).find(v=>v.id===id);if(!v||!/^[a-zA-Z0-9_-]{11}$/.test(id))return;document.dispatchEvent(new Event('tetouan-video-start'));const frame=b.closest('[data-video-frame]');frame.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0" title="${escape(v.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;frame.querySelector('iframe').focus();}});
 document.addEventListener('input',event=>{if(event.target.id==='people-query'){query=event.target.value;refresh();}});
 document.addEventListener('error',event=>{const img=event.target;if(!img.matches?.('[data-person-image]'))return;const p=people.find(p=>p.id===img.dataset.personImage);if(!p)return;const el=document.createElement('span');el.className='person-photo-fallback';el.innerHTML=`${icon('people')}<strong>${escape(text(p.name))}</strong><small>${text(T('La photographie est momentanément indisponible.','الصورة غير متاحة مؤقتاً.','The photograph is temporarily unavailable.','La fotografía no está disponible temporalmente.'))}</small>`;img.replaceWith(el);},true);
 const search=q=>people.filter(p=>normalize(Object.values(p.name).join(' ')+' '+Object.values(p.role).join(' ')).includes(normalize(q))).slice(0,6).map(p=>`<a class="search-result" href="#/personne/${p.id}" data-search-result>${portrait(p)}<span><h3>${escape(text(p.name))}</h3><small>${escape(text(p.role))}</small></span></a>`).join('');
 return {page,profile,search,nav:()=>label('nav'),title:id=>text(people.find(p=>p.id===id)?.name)};
}
